namespace smatchet {

int BranchyFunction(int x) {
    int r = 0;
    if (x == 0) r += 0;
    if (x == 1) r += 1;
    if (x == 2) r += 2;
    if (x == 3) r += 3;
    if (x == 4) r += 4;
    if (x == 5) r += 5;
    if (x == 6) r += 6;
    if (x == 7) r += 7;
    if (x == 8) r += 8;
    if (x == 9) r += 9;
    if (x == 10) r += 10;
    if (x == 11) r += 11;
    if (x == 12) r += 12;
    if (x == 13) r += 13;
    if (x == 14) r += 14;
    if (x == 15) r += 15;
    if (x == 16) r += 16;
    if (x == 17) r += 17;
    if (x == 18) r += 18;
    if (x == 19) r += 19;
    if (x == 20) r += 20;
    if (x == 21) r += 21;
    if (x == 22) r += 22;
    if (x == 23) r += 23;
    if (x == 24) r += 24;
    if (x == 25) r += 25;
    if (x == 26) r += 26;
    if (x == 27) r += 27;
    if (x == 28) r += 28;
    if (x == 29) r += 29;
    if (x == 30) r += 30;
    if (x == 31) r += 31;
    if (x == 32) r += 32;
    if (x == 33) r += 33;
    if (x == 34) r += 34;
    if (x == 35) r += 35;
    if (x == 36) r += 36;
    if (x == 37) r += 37;
    if (x == 38) r += 38;
    if (x == 39) r += 39;
    return r;
}

}  // namespace smatchet
